<?php
use Moves\Services\Finance;
use Moves\Services\FinanceContext;
use Moves\Services\ManagementDre;

$e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
$month=is_string($_GET['mes']??null)&&preg_match('/^20\d{2}-(0[1-9]|1[0-2])$/',$_GET['mes'])?$_GET['mes']:date('Y-m');
$criterion=($_GET['criterio']??'')==='caixa'?'cash':'competence'; $start=$month.'-01'; $end=date('Y-m-t',strtotime($start));
try{$dre=(new ManagementDre((int)FinanceContext::currentId()))->report($start,$end,$criterion);}catch(Throwable $error){error_log('DRE: '.$error->getMessage());$dre=null;}
$url=static fn(string $criterion):string=>\Moves\Services\AppUrl::section('dre',null,['mes'=>$month,'criterio'=>$criterion==='cash'?'caixa':'competencia']);
$lines=[['gross','Receita bruta',1],['deductions','(-) Deduções',-1],['net','(=) Receita líquida',1],['costs','(-) Custos',-1],['gross_result','(=) Resultado bruto',1],['operating','(-) Despesas operacionais',-1],['operating_result','(=) Resultado operacional',1],['other_income','(+) Outras receitas',1],['other_expense','(-) Outras despesas',-1],['result','(=) Resultado gerencial',1]];
?>
<section class="card finance-workspace finance-report" aria-labelledby="dre-title">
 <div class="finance-toolbar"><div><h2 id="dre-title">DRE gerencial</h2><p class="muted">Visão de gestão; não substitui demonstração contábil oficial.</p></div><a class="finance-button" href="/minha-conta/financeiro/exportar?<?= $e(http_build_query(['mes'=>$month])) ?>" download>Exportar lançamentos</a></div>
 <div class="finance-filter-bar"><nav class="finance-month"><a href="<?= $e(\Moves\Services\AppUrl::section('dre',null,['mes'=>date('Y-m',strtotime($start.' -1 month')),'criterio'=>$criterion==='cash'?'caixa':'competencia'])) ?>">‹</a><strong><?= $e((new DateTimeImmutable($start))->format('m/Y')) ?></strong><a href="<?= $e(\Moves\Services\AppUrl::section('dre',null,['mes'=>date('Y-m',strtotime($start.' +1 month')),'criterio'=>$criterion==='cash'?'caixa':'competencia'])) ?>">›</a></nav><nav class="finance-status"><a href="<?= $e($url('competence')) ?>"<?= $criterion==='competence'?' aria-current="true"':'' ?>>Competência</a><a href="<?= $e($url('cash')) ?>"<?= $criterion==='cash'?' aria-current="true"':'' ?>>Caixa</a></nav></div>
 <?php if($dre===null):?><div class="finance-empty"><h3>Não foi possível carregar a DRE</h3></div><?php else:$g=$dre['groups'];$net=$g['gross']['total']-$g['deductions']['total'];$gross=$net-$g['costs']['total'];$operating=$gross-$g['operating']['total'];$values=['gross'=>$g['gross']['total'],'deductions'=>$g['deductions']['total'],'net'=>$net,'costs'=>$g['costs']['total'],'gross_result'=>$gross,'operating'=>$g['operating']['total'],'operating_result'=>$operating,'other_income'=>$g['other_income']['total'],'other_expense'=>$g['other_expense']['total'],'result'=>$dre['result']]; ?>
 <p class="muted"><?= $criterion==='cash'?'Caixa considera apenas baixas recebidas e pagas na data efetiva, inclusive parciais.':'Competência considera receitas e despesas no período de competência, mesmo em aberto.' ?></p><div class="report-table-wrap"><table class="report-table"><thead><tr><th>Grupo</th><th class="is-money">Valor</th></tr></thead><tbody><?php foreach($lines as [$key,$label,$sign]):?><tr><td><details><summary><?= $e($label) ?></summary><?php if(isset($g[$key]['rows'])):foreach($g[$key]['rows'] as $row):?><small><?= $e($row['occurred_at']) ?> · <?= $e($row['description']) ?><?= $row['category']?' · '.$e($row['category']):'' ?></small><br><?php endforeach;else:?><small>Subtotal calculado.</small><?php endif;?></details></td><td class="is-money <?= $sign<0?'red':'green' ?>"><strong><?= $e(Finance::money($values[$key])) ?></strong></td></tr><?php endforeach;?></tbody></table></div><?php endif; ?>
</section>
